create table if not exists public.studio_settings (
 id text primary key default 'main', public_data jsonb not null default '{}'::jsonb,
 private_data jsonb not null default '{}'::jsonb, updated_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists public.schedule_settings (
 id text primary key default 'default', settings jsonb not null default '{}'::jsonb,
 updated_by uuid references auth.users(id) on delete set null, updated_at timestamptz not null default now()
);
create table if not exists public.notification_preferences (
 id text primary key, panel_enabled boolean not null default true, email_enabled boolean not null default false,
 priority text not null default 'normal' check(priority in('low','normal','high')), updated_by uuid references auth.users(id) on delete set null, updated_at timestamptz not null default now()
);
create table if not exists public.email_templates (
 id text primary key, subject text not null, title text not null, body text not null, signature text not null default 'Thaís Santos Beauty Studio',
 required_variables text[] not null default '{}', updated_by uuid references auth.users(id) on delete set null, updated_at timestamptz not null default now()
);
create table if not exists public.policy_versions (
 id uuid primary key default gen_random_uuid(), policy_type text not null, version integer not null,
 content text not null, is_active boolean not null default true, created_by uuid references auth.users(id) on delete set null,
 created_at timestamptz not null default now(), unique(policy_type,version)
);
create unique index if not exists one_active_policy_per_type on public.policy_versions(policy_type) where is_active;
create table if not exists public.system_settings_activity (
 id bigint generated by default as identity primary key, section text not null, action text not null,
 previous_value jsonb, new_value jsonb, performed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now()
);
create table if not exists public.admin_role_activity (
 id bigint generated by default as identity primary key, target_user uuid not null, action text not null,
 performed_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now()
);

alter table public.studio_settings enable row level security; alter table public.schedule_settings enable row level security;
alter table public.notification_preferences enable row level security; alter table public.email_templates enable row level security;
alter table public.policy_versions enable row level security; alter table public.system_settings_activity enable row level security;
alter table public.admin_role_activity enable row level security;
create policy "Admins manage studio settings" on public.studio_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins manage schedule settings" on public.schedule_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins manage notification preferences" on public.notification_preferences for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins manage email templates" on public.email_templates for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins manage policy versions" on public.policy_versions for all to authenticated using(public.is_admin()) with check(public.is_admin());
create policy "Admins read settings activity" on public.system_settings_activity for select to authenticated using(public.is_admin());
create policy "Admins read role activity" on public.admin_role_activity for select to authenticated using(public.is_admin());

