create or replace function public.get_public_settings() returns jsonb language sql stable security definer set search_path=public as $$
 select jsonb_build_object('studio',coalesce((select public_data from public.studio_settings where id='main'),'{}'::jsonb),'schedule',coalesce((select settings from public.schedule_settings where id='default'),'{}'::jsonb),'policies',coalesce((select jsonb_object_agg(policy_type,jsonb_build_object('id',id,'version',version,'content',content)) from public.policy_versions where is_active),'{}'::jsonb)) $$;

create or replace function public.admin_get_settings() returns jsonb language plpgsql security definer set search_path=public as $$ begin
 if not public.is_admin() then raise exception 'Acesso administrativo necessário'; end if;
 return jsonb_build_object('studio',(select to_jsonb(s) from public.studio_settings s where id='main'),'schedule',(select to_jsonb(s) from public.schedule_settings s where id='default'),'policies',(select coalesce(jsonb_agg(to_jsonb(p) order by p.policy_type,p.version desc),'[]') from public.policy_versions p),'notifications',(select coalesce(jsonb_agg(to_jsonb(n) order by n.id),'[]') from public.notification_preferences n),'templates',(select coalesce(jsonb_agg(to_jsonb(e) order by e.id),'[]') from public.email_templates e),'admins',(select coalesce(jsonb_agg(jsonb_build_object('id',u.id,'name',coalesce(u.raw_user_meta_data->>'name',split_part(u.email,'@',1)),'email',u.email,'created_at',u.created_at,'last_sign_in_at',u.last_sign_in_at,'role',u.raw_app_meta_data->>'role')),'[]') from auth.users u where u.raw_app_meta_data->>'role'='admin'));
end $$;

create or replace function public.admin_save_settings(section text,payload jsonb) returns void language plpgsql security definer set search_path=public as $$ declare old jsonb; begin
 if not public.is_admin() then raise exception 'Acesso administrativo necessário'; end if;
 if section='profile' or section='payments' or section='site' then select case when section='profile' or section='site' then public_data else private_data end into old from public.studio_settings where id='main'; update public.studio_settings set public_data=case when section in('profile','site') then public_data||payload else public_data end,private_data=case when section='payments' then private_data||payload else private_data end,updated_by=auth.uid(),updated_at=now() where id='main';
 elsif section='schedule' then select settings into old from public.schedule_settings where id='default'; update public.schedule_settings set settings=payload,updated_by=auth.uid(),updated_at=now() where id='default';
 else raise exception 'Seção inválida'; end if;
 insert into public.system_settings_activity(section,action,previous_value,new_value,performed_by) values(section,'updated',case when section='payments' then jsonb_build_object('masked',true) else old end,case when section='payments' then jsonb_build_object('masked',true) else payload end,auth.uid());
end $$;

create or replace function public.admin_save_policy(target_type text,target_content text) returns uuid language plpgsql security definer set search_path=public as $$ declare result uuid; next_version integer; begin
 if not public.is_admin() then raise exception 'Acesso administrativo necessário'; end if; if trim(target_content)='' then raise exception 'O texto da política é obrigatório'; end if;
 select coalesce(max(version),0)+1 into next_version from public.policy_versions where policy_type=target_type; update public.policy_versions set is_active=false where policy_type=target_type and is_active;
 insert into public.policy_versions(policy_type,version,content,created_by) values(target_type,next_version,target_content,auth.uid()) returning id into result;
 insert into public.system_settings_activity(section,action,new_value,performed_by) values('policies','version_created',jsonb_build_object('type',target_type,'version',next_version),auth.uid()); return result;
end $$;

create or replace function public.admin_save_notifications(payload jsonb) returns void language plpgsql security definer set search_path=public as $$ declare item jsonb; begin if not public.is_admin() then raise exception 'Acesso negado'; end if; for item in select * from jsonb_array_elements(payload) loop update public.notification_preferences set panel_enabled=(item->>'panel_enabled')::boolean,email_enabled=(item->>'email_enabled')::boolean,priority=item->>'priority',updated_by=auth.uid(),updated_at=now() where id=item->>'id'; end loop; insert into public.system_settings_activity(section,action,new_value,performed_by) values('notifications','updated',payload,auth.uid()); end $$;
create or replace function public.admin_save_email_template(payload jsonb) returns void language plpgsql security definer set search_path=public as $$ declare required text; begin if not public.is_admin() then raise exception 'Acesso negado'; end if; for required in select unnest(required_variables) from public.email_templates where id=payload->>'id' loop if position(required in payload->>'body')=0 then raise exception 'A variável obrigatória % não pode ser removida',required; end if; end loop; update public.email_templates set subject=payload->>'subject',title=payload->>'title',body=payload->>'body',signature=payload->>'signature',updated_by=auth.uid(),updated_at=now() where id=payload->>'id'; insert into public.system_settings_activity(section,action,new_value,performed_by) values('emails','template_updated',jsonb_build_object('id',payload->>'id'),auth.uid()); end $$;

create or replace function public.admin_set_role(target_email text,make_admin boolean) returns void language plpgsql security definer set search_path=public as $$ declare target auth.users%rowtype; admin_count integer; begin
 if not public.is_admin() then raise exception 'Acesso negado'; end if; select * into target from auth.users where lower(email)=lower(trim(target_email)); if not found then raise exception 'Conta não encontrada'; end if;
 if not make_admin then select count(*) into admin_count from auth.users where raw_app_meta_data->>'role'='admin'; if admin_count<=1 then raise exception 'O sistema precisa manter ao menos um administrador'; end if; if target.id=auth.uid() and admin_count<=1 then raise exception 'O último administrador não pode remover a própria permissão'; end if; end if;
 update auth.users set raw_app_meta_data=case when make_admin then coalesce(raw_app_meta_data,'{}')||'{"role":"admin"}'::jsonb else coalesce(raw_app_meta_data,'{}')-'role' end where id=target.id;
 insert into public.admin_role_activity(target_user,action,performed_by) values(target.id,case when make_admin then 'promoted' else 'removed' end,auth.uid());
end $$;

grant execute on function public.get_public_settings() to anon,authenticated; grant execute on function public.admin_get_settings() to authenticated;
grant execute on function public.admin_save_settings(text,jsonb) to authenticated; grant execute on function public.admin_save_policy(text,text) to authenticated;
grant execute on function public.admin_save_notifications(jsonb) to authenticated; grant execute on function public.admin_save_email_template(jsonb) to authenticated;
grant execute on function public.admin_set_role(text,boolean) to authenticated;
